class Solution {
  public int kEmptySlots(int[] bulbs, int k) {
    int n = bulbs.length;
    int[] day = new int[n]; // day[i]: when position i turns on (1-based)
    for (int d = 0; d < n; d++) day[bulbs[d] - 1] = d + 1;
    int best = Integer.MAX_VALUE;
    // window [left, right] with right = left + k + 1: every inner bulb must turn on after both ends
    for (int left = 0, right = k + 1, i = 1; right < n; i++) {
      if (i == right) {
        best = Math.min(best, Math.max(day[left], day[right]));
        left = i;
        right = left + k + 1;
      } else if (day[i] < day[left] || day[i] < day[right]) {
        left = i;
        right = left + k + 1;
      }
    }
    return best == Integer.MAX_VALUE ? -1 : best;
  }
}
